132	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
133	    @Override
134	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
135	        // Idempotent create: if this request carries an Idempotency-Key we have already created an
136	        // owner for, return that original owner with 200 OK instead of creating a duplicate.
137	        String idempotencyKey = request.getHeader(IDEMPOTENCY_KEY_HEADER);
138	        boolean hasIdempotencyKey = idempotencyKey != null && !idempotencyKey.isBlank();
139	        if (hasIdempotencyKey) {
140	            Optional<Owner> existing = this.idempotencyStore.find(idempotencyKey)
141	                .map(this.clinicService::findOwnerById);
142	            if (existing.isPresent()) {
143	                return new ResponseEntity<>(ownerMapper.toOwnerDto(existing.get()), HttpStatus.OK);
144	            }
145	        }
146	        HttpHeaders headers = new HttpHeaders();
147	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
148	        // The effective registration date (supplied, or the server date when omitted) must fall on
149	        // a business day: a weekend rolls forward to the next Monday. Everything derived from the
150	        // registration date — the stored value, the per-day limit below and the membership number —
151	        // uses this adjusted date.
152	        LocalDate effectiveDate = BusinessDays.effectiveRegistrationDate(owner.getRegistrationDate());
153	        owner.setRegistrationDate(effectiveDate);
154	        // Per-day capacity: once the day has reached its limit of newly created owners, reject
155	        // further creates for that day with 429 Too Many Requests.
156	        int ownersRegisteredToday = this.clinicService.countOwnersRegisteredOn(effectiveDate);
157	        if (ownersRegisteredToday >= DAILY_REGISTRATION_LIMIT) {
158	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
159	        }
160	        // Bulk-signup warning: flag this owner when more than 80 owners have already been created
161	        // for its registration date, signalling a bulk-signup surge.
162	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
163	        // Per-city capacity: a city that already holds the maximum number of owners is full.
164	        if (this.clinicService.countOwnersInCity(owner.getCity()) >= CITY_CAPACITY) {
165	            return new ResponseEntity<>(HttpStatus.CONFLICT);
166	        }
167	        // The household id is derived deterministically on the owner itself (see
168	        // Owner.getHouseholdId()) from its normalized last name and postcode, so owners sharing a
169	        // last name and postcode share it automatically — no linking step and no ordering to manage.
170	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
171	        // Exact-identity hard duplicate: reject with 409 when the new owner's WHOLE identityKey
172	        // (the SHA-256 of normalized telephone | lower-cased email-or-empty | soundex(lastName))
173	        // equals an existing owner's. A truly identical record is always rejected, independent of
174	        // sharesHousehold.
175	        if (this.clinicService.isIdentityKeyInUse(owner)) {
176	            return new ResponseEntity<>(HttpStatus.CONFLICT);
177	        }
178	        // Household membership: another owner may already belong to this (last name, postcode)
179	        // household. A new member is admitted rather than rejected — its membership level is instead
180	        // capped relative to the household (see below). An undeclared member (sharesHousehold not
181	        // set) that is not an exact-identity duplicate is still allowed through, flagged as a
182	        // possible duplicate for review.
183	        boolean householdInUse = this.clinicService.isHouseholdInUse(owner);
184	        // Soft "possible duplicate" detection: an existing owner's last name has the same Soundex
185	        // code and the same postcode, while its identity key differs (so it is not a hard
186	        // duplicate). A declared household member (sharesHousehold on an in-use household) is an
187	        // intentional share, not a suspected duplicate, so it is not flagged; otherwise the create
188	        // still proceeds, flagged with possibleDuplicate=true and possibleDuplicateOf set to the
189	        // matching owner id.
190	        Integer possibleDuplicateOf = (householdInUse && sharesHousehold)
191	            ? null
192	            : this.clinicService.findPossibleDuplicateOwnerId(owner);
193	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
194	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
195	        owner.setNamesakeCount(
196	            this.clinicService.countNamesakes(owner.getFirstName(), owner.getLastName()));
197	        // Membership-level ceiling: a new owner's membershipLevel may not exceed one above the
198	        // current maximum level among its existing household members. Derive the cap from those
199	        // members' effective (already-capped) levels; with no existing member the cap stays null
200	        // and the owner's level is used uncapped.
201	        Collection<Owner> householdMembers = this.clinicService.findHouseholdMembers(owner);
202	        if (!householdMembers.isEmpty()) {
203	            int maxHouseholdLevel = householdMembers.stream()
204	                .mapToInt(member -> ownerMapper.formatMembershipLevel(member))
205	                .max()
206	                .getAsInt();
207	            owner.setMembershipLevelCap(maxHouseholdLevel + 1);
208	        }
209	        this.clinicService.saveOwner(owner);
210	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
211	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
212	            ownerMapper.formatMembershipLevel(owner), ownerMapper.formatMembershipNumber(owner));
213	        if (hasIdempotencyKey) {
214	            this.idempotencyStore.record(idempotencyKey, owner.getId());
215	        }
216	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
217	        headers.setLocation(UriComponentsBuilder.newInstance()
218	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
219	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
220	    }
