222	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
223	    @Override
224	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
225	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
226	        if (currentOwner == null) {
227	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
228	        }
229	        currentOwner.setAddressLine1(ownerMapper.normalizeAddress(ownerFieldsDto.getAddressLine1()));
230	        currentOwner.setAddressLine2(ownerMapper.normalizeAddress(ownerFieldsDto.getAddressLine2()));
231	        currentOwner.setAddress(ownerMapper.composeAddress(ownerFieldsDto));
232	        currentOwner.setCity(ownerFieldsDto.getCity());
233	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
234	        currentOwner.setLastName(ownerFieldsDto.getLastName());
235	        currentOwner.setTelephone(ownerMapper.normalizeTelephone(ownerFieldsDto.getTelephone()));
236	        currentOwner.setEmail(ownerMapper.normalizeEmail(ownerFieldsDto.getEmail()));
237	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
238	        this.clinicService.saveOwner(currentOwner);
239	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
240	    }
241	
242	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
243	    @Transactional
244	    @Override
245	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
246	        Owner owner = this.clinicService.findOwnerById(ownerId);
247	        if (owner == null) {
248	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
249	        }
250	        this.clinicService.deleteOwner(owner);
251	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
252	    }
