273	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
274	    @Override
275	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
276	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
277	        if (currentOwner != null) {
278	            Pet currentPet = this.clinicService.findPetById(petId);
279	            if (currentPet != null) {
280	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
281	                currentPet.setName(petFieldsDto.getName());
282	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
283	                this.clinicService.savePet(currentPet);
284	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
285	            }
286	        }
287	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
288	    }
