258	    /**
259	     * The single derived key behind all duplicate detection: the lower-case hex SHA-256 (64 hex
260	     * characters) of {@code <normalizedTelephone>|<lowerEmail>|<soundex(lastName)>}, where the
261	     * telephone is the stored (normalized) value or an empty string when absent, the email is
262	     * lower-cased or an empty string when absent, and the surname component is the standard Soundex
263	     * code of the last name (see {@link org.springframework.samples.petclinic.util.Soundex}).
264	     * Because the telephone is part of the key, two owners are duplicates only when their WHOLE
265	     * identity keys are equal; two owners sharing a surname (hence Soundex) and postcode but with
266	     * different telephones have different identity keys and are therefore both allowed, surfacing
267	     * instead as a soft possible-duplicate match.
268	     */
269	    @Transient
270	    public String getIdentityKey() {
271	        String telephone = this.telephone == null ? "" : this.telephone;
272	        String email = this.email == null ? "" : this.email.toLowerCase();
273	        String key = telephone + "|" + email + "|" + Soundex.encode(getLastName());
274	        return sha256Hex(key, 32);
275	    }
