277	    /**
278	     * The deterministic household identifier derived from the owner's own fields, mirroring
279	     * {@link #getIdentityKey()}: the first twelve lower-case hex characters (the first six bytes)
280	     * of the SHA-256 of {@code <normalizedLastName>|<postcode>}, where the last name is normalized
281	     * by trimming, collapsing internal whitespace and lower-casing, and an absent postcode counts
282	     * as empty. Because it is a pure function of the stored last name and postcode, every owner
283	     * sharing both automatically carries the same value, with no linking step or stored column.
284	     */
285	    @Transient
286	    public String getHouseholdId() {
287	        String lastName = getLastName() == null ? ""
288	            : getLastName().trim().replaceAll("\\s+", " ").toLowerCase();
289	        String key = lastName + "|" + (this.postcode == null ? "" : this.postcode);
290	        return sha256Hex(key, 6);
291	    }
292	
293	    /**
294	     * The lower-case hex SHA-256 of {@code value}, truncated to the first {@code bytes} bytes
295	     * (so {@code 2 * bytes} hex characters). Shared by the derived identity and household keys so
296	     * the two stay consistent; they differ only in how many leading bytes they keep.
297	     */
298	    private static String sha256Hex(String value, int bytes) {
299	        try {
300	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
301	            StringBuilder sb = new StringBuilder(bytes * 2);
302	            for (int i = 0; i < bytes; i++) {
303	                sb.append(String.format("%02x", digest[i]));
304	            }
305	            return sb.toString();
306	        }
307	        catch (NoSuchAlgorithmException e) {
308	            throw new IllegalStateException("SHA-256 not available", e);
309	        }
310	    }
