403	    /**
404	     * Normalize an email address for storage by lower-casing it, so it is persisted and
405	     * returned in a canonical form regardless of the casing supplied by the caller.
406	     * Syntactic validity is enforced separately by the {@code @Email} constraint on the DTO.
407	     * {@code @Named} keeps this out of MapStruct's automatic method selection, so it only
408	     * runs where a mapping explicitly references it via {@code qualifiedByName}.
409	     */
410	    @Named("normalizeEmail")
411	    default String normalizeEmail(String email) {
412	        return email == null ? null : email.toLowerCase();
