243	    @Override
244	    @Transactional
245	    public void saveOwner(Owner owner) throws DataAccessException {
246	        if (owner.getCustomerCode() == null) {
247	            owner.setCustomerCode(generateCustomerCode(owner));
248	        }
249	        ownerRepository.save(owner);
250	
251	    }
252	
253	    /**
254	     * Build a {@code customerCode} of the form {@code <REGION>-<HASH8>}: the region code derived
255	     * from the owner's postcode (see {@link Regions#forPostcode}), a hyphen, and {@code HASH8} —
256	     * the first eight upper-case hex characters of the SHA-256 of the owner's normalized telephone
257	     * concatenated with its last name (e.g. {@code NSW-3F5A9C2E}). The identity carries no sequence
258	     * number, so it depends only on the owner's own postcode, telephone and last name.
259	     *
260	     * <p>If the computed code collides with an existing owner's {@code customerCode}, {@code -<n>}
261	     * is appended with the smallest {@code n} of 2 or more that makes it unique, and the
262	     * de-duplicated code is returned.
263	     */
264	    private String generateCustomerCode(Owner owner) {
265	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
266	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
267	        String base = Regions.forPostcode(owner.getPostcode()) + "-" + hash8(telephone + lastName);
268	        return deduplicateCustomerCode(base, owner);
269	    }
270	
271	    /**
272	     * Return {@code base} if no other owner already uses it as a {@code customerCode}; otherwise
273	     * append {@code -<n>} with the smallest {@code n >= 2} that is not already taken, so distinct
274	     * owners always receive distinct customer codes.
275	     */
276	    private String deduplicateCustomerCode(String base, Owner owner) {
277	        Set<String> existing = ownerRepository.findAll().stream()
278	            .filter(other -> other != owner)
279	            .map(Owner::getCustomerCode)
280	            .filter(Objects::nonNull)
281	            .collect(Collectors.toSet());
282	        if (!existing.contains(base)) {
283	            return base;
284	        }
285	        int n = 2;
286	        while (existing.contains(base + "-" + n)) {
287	            n++;
288	        }
289	        return base + "-" + n;
290	    }
291	
292	    /**
293	     * The first eight upper-case hex characters (the first four bytes) of the SHA-256 of
294	     * {@code value}, the {@code HASH8} segment of a {@code customerCode}.
295	     */
296	    private static String hash8(String value) {
297	        try {
298	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
299	            StringBuilder sb = new StringBuilder(8);
300	            for (int i = 0; i < 4; i++) {
301	                sb.append(String.format("%02X", digest[i]));
302	            }
303	            return sb.toString();
304	        }
305	        catch (NoSuchAlgorithmException e) {
306	            throw new IllegalStateException("SHA-256 not available", e);
307	        }
308	    }
