322	    @Override
323	    @Transactional(readOnly = true)
324	    public Collection<Owner> findHouseholdMembers(Owner owner) throws DataAccessException {
325	        String householdId = owner.getHouseholdId();
326	        if (householdId == null) {
327	            return List.of();
328	        }
329	        return ownerRepository.findAll().stream()
330	            .filter(existing -> existing.getId() != null)
331	            .filter(existing -> !existing.isDeleted())
332	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
333	            .collect(Collectors.toList());
334	    }
