336	    /**
337	     * Canonicalize a free-text value for equality comparison: trim, collapse every run of
338	     * whitespace to a single space and lower-case the result, so values that differ only in
339	     * letter case or incidental whitespace are treated as equal. Used by the per-city matching
340	     * rule.
341	     */
342	    private String normalizeForComparison(String value) {
343	        if (value == null) {
344	            return null;
345	        }
346	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
347	    }
